public:
    bool partitionArray(vector<int>& nums, int k) {
        if (nums.size() % k) return false;
        unordered_map<int,int> cnt;
        int mx = 0;
        for (int x : nums) mx = max(mx, ++cnt[x]);
        return mx <= (int)nums.size() / k;
    }
};

