from collections import Counter
class Solution:
    def partitionArray(self, nums: List[int], k: int) -> bool:
        cnt = Counter(nums)
        g = len(nums) // k
        if len(nums) % k or max(cnt.values()) > g:
            return False
        groups = [[] for _ in range(g)]
        for v, c in sorted(cnt.items(), key=lambda kv: -kv[1]):
            for j in range(c):
                groups[j % g].append(v)
        return True

