class Solution {
    public boolean partitionArray(int[] nums, int k) {
        Map<Integer,Integer> cnt = new HashMap<>();
        for (int x : nums) cnt.merge(x, 1, Integer::sum);
        int g = nums.length / k;
        if (nums.length % k != 0) return false;
        List<Map.Entry<Integer,Integer>> v = new ArrayList<>(cnt.entrySet());
        v.sort((a, b) -> b.getValue() - a.getValue());
        if (v.get(0).getValue() > g) return false;
        List<List<Integer>> groups = new ArrayList<>();
        for (int i = 0; i < g; i++) groups.add(new ArrayList<>());
        int idx = 0;
        for (var e : v)
            for (int j = 0; j < e.getValue(); j++) groups.get(idx++ % g).add(e.getKey());
        return true;
    }
}

